#include "visit_appointment_commitments.hpp"
#include "visit_appointment_detail.hpp"
#include <set>
namespace hanmo::resident {namespace {
struct Event{StableId fact,subject,actor;Integer tick=0,first=0,last=0;bool close=false;};
bool closed_now(const VisitAppointmentMeetingState* state,const StableId& id,Integer tick){if(!state)return false;for(const auto& row:state->cancelled.rows())if(row.second.invitation_fact_id==id&&row.second.contact.tick<=tick)return true;for(const auto& row:state->finished.rows())if(row.second.invitation_fact_id==id&&row.second.tick<=tick)return true;return false;}
}
Status check_visit_appointment_current_commitment(const CommonStore& common,const VisitAppointmentState& invitations,const VisitAppointmentMeetingState* meetings,const StableId& actor,Integer earliest,Integer latest,const StableId& excluding,const CurrentMomentRead* clock){Integer current=common.tick();if(invitations.version==2){if(!clock)return common_failure("VisitAppointmentActualClockRequired",{},ErrorKind::unsupported_capability);auto at=clock->read_current_moment();if(!at.ok)return {false,{},at.error};current=at.value.half_day_tick;}if(!common.actor(actor)||earliest<0||latest<earliest)return common_failure("InvalidVisitAppointmentCommitmentQuery",actor);for(const auto& row:invitations.offered.rows()){const auto& offer=row.second;if(row.first==excluding||closed_now(meetings,row.first,current)||!visit_appointment_detail::overlap(earliest,latest,offer.terms.earliest_tick,offer.terms.latest_tick))continue;bool own=offer.terms.inviter_actor_id==actor;if(!own&&offer.terms.invitee_actor_id==actor){const auto* accepted=visit_appointment_detail::accepted(invitations,row.first);own=accepted&&accepted->actor_id==actor&&accepted->tick<=current;}if(own)return common_failure("VisitAppointmentCommitmentConflict",row.first);}return common_success();}
Status validate_visit_appointment_commitment_history(const CommonStore& common,const PersonalAppointmentState& personal,const VisitAppointmentState& invitations,const VisitAppointmentMeetingState& meetings,const CurrentMomentRead* clock){Integer current=common.tick();if(invitations.version==2){if(!clock)return common_failure("VisitAppointmentActualClockRequired",{},ErrorKind::unsupported_capability);auto at=clock->read_current_moment();if(!at.ok)return {false,{},at.error};current=at.value.half_day_tick;}std::map<StableId,std::vector<Event>> by_fact;
 for(const auto& row:personal.accepted.rows()){const auto& a=row.second;for(const auto& actor:{a.contact.actor_id,a.contact.provider_actor_id})by_fact[row.first].push_back({row.first,row.first,actor,a.contact.tick,a.earliest_tick,a.latest_tick,false});}
 for(const auto& row:personal.cancelled.rows())by_fact[row.first].push_back({row.first,row.second.appointment_id,{},row.second.contact.tick,0,0,true});for(const auto& row:personal.finished.rows())by_fact[row.first].push_back({row.first,row.second.appointment_id,{},row.second.tick,0,0,true});
 for(const auto& row:invitations.offered.rows()){const auto& t=row.second.terms;by_fact[row.first].push_back({row.first,row.first,t.inviter_actor_id,t.offered_tick,t.earliest_tick,t.latest_tick,false});}for(const auto& row:invitations.accepted.rows()){const auto* offer=invitations.offered.find(row.second.invitation_fact_id);if(!offer)return common_failure("VisitAppointmentCommitmentSourceRequired",row.first);const auto& t=offer->terms;by_fact[row.first].push_back({row.first,offer->fact_id,row.second.actor_id,row.second.tick,t.earliest_tick,t.latest_tick,false});}
 for(const auto& row:meetings.cancelled.rows())by_fact[row.first].push_back({row.first,row.second.invitation_fact_id,{},row.second.contact.tick,0,0,true});for(const auto& row:meetings.finished.rows())by_fact[row.first].push_back({row.first,row.second.invitation_fact_id,{},row.second.tick,0,0,true});
 std::vector<Event> active;std::set<StableId> closed;Integer previous=0,previous_tick=-1;std::size_t covered=0;
 for(const auto& head:common.state().facts.rows()){const auto found=by_fact.find(head.first);if(found==by_fact.end())continue;++covered;const auto colon=head.first.find(':');const auto instance=colon==StableId::npos?std::optional<Integer>{}:visit_appointment_detail::serial(head.first,head.first.substr(0,colon),common.state().next_instance_id);if(!instance||*instance<=previous)return common_failure("VisitAppointmentCommitmentOrderMismatch",head.first);previous=*instance;
  for(const auto& event:found->second){if(event.tick<previous_tick||event.tick>current)return common_failure("VisitAppointmentCommitmentClockMismatch",head.first);previous_tick=event.tick;if(event.close){if(!closed.insert(event.subject).second)return common_failure("VisitAppointmentCommitmentAlreadyClosed",head.first);continue;}if(closed.count(event.subject))return common_failure("VisitAppointmentCommitmentReopened",head.first);for(const auto& old:active)if(!closed.count(old.subject)&&old.actor==event.actor&&old.last>=event.tick&&visit_appointment_detail::overlap(old.first,old.last,event.first,event.last))return common_failure("VisitAppointmentCommitmentConflict",head.first);active.push_back(event);}
 }
 return covered==by_fact.size()?common_success():common_failure("VisitAppointmentCommitmentFactCoverageMismatch");}
}
